#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<long long> greed(n);
    for (int i = 0; i < n; i++) cin >> greed[i];
    vector<long long> cookies(m);
    for (int i = 0; i < m; i++) cin >> cookies[i];

    sort(greed.begin(), greed.end());
    sort(cookies.begin(), cookies.end());
    long long child = 0;
    for (long long size : cookies) {
        if (child < n && size >= greed[child]) child++;
    }
    cout << child << "\n";

    return 0;
}

