import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] greed = new long[(int) n];
        for (int i = 0; i < greed.length; i++) greed[i] = Long.parseLong(next());
        long[] cookies = new long[(int) m];
        for (int i = 0; i < cookies.length; i++) cookies[i] = Long.parseLong(next());

        Arrays.sort(greed);
        Arrays.sort(cookies);
        int child = 0;
        for (int j = 0; j < m; j++) {
            if (child < n && cookies[j] >= greed[child]) child++;
        }
        System.out.println(child);
    }
}
